create extension if not exists pgcrypto;
create type public.user_role as enum ('client','freelancer','admin');
create type public.order_status as enum ('pending','active','in_progress','delivered','revision_requested','completed','cancelled','disputed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, username text unique, role public.user_role not null default 'client', bio text, location text, avatar_url text, verified boolean not null default false, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique);
create table public.services (id uuid primary key default gen_random_uuid(), freelancer_id uuid not null references public.profiles(id) on delete cascade, category_id uuid references public.categories(id), title text not null, description text, price_pkr numeric(12,2) not null default 0, delivery_days int not null default 1, rating numeric(3,2) not null default 0, review_count int not null default 0, published boolean not null default false, created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.profiles(id) on delete cascade, category_id uuid references public.categories(id), title text not null, description text, budget_min numeric(12,2), budget_max numeric(12,2), deadline date, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.profiles(id), freelancer_id uuid not null references public.profiles(id), service_id uuid references public.services(id), project_id uuid references public.projects(id), amount_pkr numeric(12,2) not null, status public.order_status not null default 'pending', requirements text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.messages (id uuid primary key default gen_random_uuid(), order_id uuid references public.orders(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete cascade, body text not null, created_at timestamptz not null default now());
create table public.reviews (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, reviewer_id uuid not null references public.profiles(id), reviewee_id uuid not null references public.profiles(id), rating int not null check (rating between 1 and 5), body text, created_at timestamptz not null default now());
create table public.transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, order_id uuid references public.orders(id), amount_pkr numeric(12,2) not null, type text not null check (type in ('payment','refund','withdrawal','fee')), status text not null default 'pending', created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.services enable row level security; alter table public.projects enable row level security; alter table public.orders enable row level security; alter table public.messages enable row level security; alter table public.reviews enable row level security; alter table public.transactions enable row level security;
create policy "public profiles readable" on public.profiles for select using (true);
create policy "users update own profile" on public.profiles for update using (auth.uid()=id);
create policy "published services readable" on public.services for select using (published=true or auth.uid()=freelancer_id);
create policy "users create own projects" on public.projects for insert with check (auth.uid()=client_id);
create policy "project owners read projects" on public.projects for select using (auth.uid()=client_id);
create policy "order participants read orders" on public.orders for select using (auth.uid()=client_id or auth.uid()=freelancer_id);
create policy "order participants read messages" on public.messages for select using (exists(select 1 from public.orders o where o.id=order_id and (o.client_id=auth.uid() or o.freelancer_id=auth.uid())));
create policy "participants send messages" on public.messages for insert with check (auth.uid()=sender_id and exists(select 1 from public.orders o where o.id=order_id and (o.client_id=auth.uid() or o.freelancer_id=auth.uid())));
